package com.mavric.health.persistence.sqlserver;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.ApiException;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real REQUIRED templates, modeled executor/manager: no connected health or durability proof. */
class SqlServerMonitorStoreTest {
 static final String ID="aa000000-0000-4000-8000-000000000001";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final SqlServerMonitorStore store=new SqlServerMonitorStore(executor,manager);
 final Deque<SqlServerExecutor.Result> results=new ArrayDeque<>();final List<SqlServerProcedure> calls=new ArrayList<>();final List<SqlServerContext> contexts=new ArrayList<>();final List<List<Object>> args=new ArrayList<>();final MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/public/status");
 SqlServerMonitorStoreTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());calls.add(inv.getArgument(0));contexts.add(inv.getArgument(1));args.add(Arrays.asList(((Object[])inv.getRawArguments()[2]).clone()));return results.removeFirst();});}
 void row(Map<String,Object> row){results.add(new SqlServerExecutor.Result(List.of(List.of(row)),List.of(0)));}
 void probe(){row(Map.of("ready",1));results.add(new SqlServerExecutor.Result(List.of(),List.of(0)));}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 static void safe(Runnable work){var error=assertThrows(ApiException.class,work::run);assertEquals(500,error.status);assertEquals("DATABASE_ERROR",error.code);assertNull(error.getCause());assertFalse(error.toString().contains("canary"));}
 @Test void statusThreeModesExactFourFieldsImmutableAndContexts(){for(String mode:List.of("OPEN","READ_ONLY","MAINTENANCE")){row(Map.of("mode",mode,"message","","revision",1,"passwordHash","canary"));var out=store.status(request);assertEquals(Map.of("mode",mode,"message","","revision",1,"status",mode.equals("OPEN")?"OPERATIONAL":"RESTRICTED"),out);assertThrows(UnsupportedOperationException.class,out::clear);assertEquals(List.of(),args.getLast());assertEquals(SqlServerContext.Scope.REQUEST,contexts.getLast().scope());}assertEquals(Collections.nCopies(3,SqlServerProcedure.APPLICATION_STATUS),calls);}
 @Test void statusAcceptsTenantAndPlatformButNotMalformedHost(){request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));row(Map.of("mode","OPEN","message","synthetic","revision",2));store.status(request);assertEquals(ID,contexts.getLast().tenantId());request.removeAttribute("health.tenant");request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SOP"),"a".repeat(64)));row(Map.of("mode","OPEN","message","synthetic","revision",2));store.status(request);assertEquals(ID,contexts.getLast().actorId());request.setAttribute("health.tenant","forged");safe(()->store.status(request));safe(()->store.status(null));assertEquals(2,calls.size());}
 @Test void invalidStatusResultsetsColumnsAndExactTypesRollback(){for(String key:List.of("mode","message","revision"))for(Object value:Arrays.asList(null,true,0L)){var row=new LinkedHashMap<String,Object>(Map.of("mode","OPEN","message","x","revision",1));row.put(key,value);row(row);safe(()->store.status(request));assertEquals("rollback",manager.events.getLast());}row(Map.of("mode","INVALID","message","x","revision",1));safe(()->store.status(request));row(Map.of("mode","OPEN","message","x","revision",0));safe(()->store.status(request));results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.status(request));results.add(new SqlServerExecutor.Result(List.of(List.of(),List.of()),List.of()));safe(()->store.status(request));}
 @Test void workerContextIgnoresHttpAndSampleHasExactLongMetrics(){var prior=new MockHttpServletRequest("POST","/forged");TraceContext.REQUEST.set(prior);probe();store.sample(ID,Long.MAX_VALUE,0,Long.MAX_VALUE);assertSame(prior,TraceContext.REQUEST.get());assertEquals(List.of(SqlServerProcedure.HEALTH_READY,SqlServerProcedure.HEALTH_SAMPLE),calls);assertEquals(List.of(),args.getFirst());var values=args.getLast();assertEquals(6,values.size());assertEquals(ID,values.get(0));assertEquals("UP",values.get(1));assertTrue(values.get(2) instanceof Long);assertTrue((Long)values.get(2)>=0);assertEquals(Long.MAX_VALUE,values.get(3));assertEquals(0L,values.get(4));assertEquals(Long.MAX_VALUE,values.get(5));for(var c:contexts){assertEquals(new SqlServerContext(null,null,null,null,null,null,null,null,null,SqlServerContext.Scope.WORKER),c);}assertEquals(List.of("begin:0","commit"),manager.events);}
 @Test void invalidMetricsBeforeProbeAndBadReadyNeverWritesSample(){for(String id:Arrays.asList(null,"bad",ID.toUpperCase(Locale.ROOT)))assertEquals(400,assertThrows(ApiException.class,()->store.sample(id,0,0,0)).status);for(int index=0;index<3;index++){long[] m={0,0,0};m[index]=-1;assertEquals(400,assertThrows(ApiException.class,()->store.sample(ID,m[0],m[1],m[2])).status);}verifyNoInteractions(executor);for(Object ready:Arrays.asList(null,0,1L,true,"1")){var row=new LinkedHashMap<String,Object>();row.put("ready",ready);row(row);safe(()->store.sample(ID,0,0,0));}results.add(new SqlServerExecutor.Result(List.of(),List.of()));safe(()->store.sample(ID,0,0,0));assertFalse(calls.contains(SqlServerProcedure.HEALTH_SAMPLE));}
 @Test void requiredJoinProbeWriteAndCommitErrorsNeverPartialOrRetry(){probe();assertThrows(RuntimeException.class,()->manager.outer(()->{store.sample(ID,0,0,0);assertEquals(List.of("begin:0"),manager.events);throw new RuntimeException("synthetic cancellation");}));assertEquals("rollback",manager.events.getLast());row(Map.of("ready",1));results.add(new SqlServerExecutor.Result(List.of(List.of()),List.of()));safe(()->store.sample(ID,0,0,0));probe();manager.failCommit=true;safe(()->store.sample(ID,0,0,0));doThrow(new RuntimeException(new java.sql.SQLException("canary",null,229))).when(executor).execute(any(),any(),any(Object[].class));safe(()->store.sample(ID,0,0,0));verify(executor,times(7)).execute(any(),any(),any(Object[].class));}
 @Test void probeResultsetAndRowCardinalityMustBeExactlyOne(){for(var sets:List.<List<List<Map<String,Object>>>>of(List.of(List.of()),List.of(List.of(Map.of("ready",1),Map.of("ready",1))),List.of(List.of(Map.of("ready",1)),List.of()))){results.add(new SqlServerExecutor.Result(sets,List.of()));safe(()->store.sample(ID,0,0,0));assertEquals("rollback",manager.events.getLast());}assertEquals(Collections.nCopies(3,SqlServerProcedure.HEALTH_READY),calls);}
 @Test void writeSqlFailurePropagatesAndDoesNotRetryOrRecordDown(){doAnswer(inv->{var sp=inv.<SqlServerProcedure>getArgument(0);calls.add(sp);if(sp==SqlServerProcedure.HEALTH_READY)return new SqlServerExecutor.Result(List.of(List.of(Map.of("ready",1))),List.of());throw new RuntimeException(new java.sql.SQLException("canary driver",null,51003));}).when(executor).execute(any(),any(),any(Object[].class));var error=assertThrows(ApiException.class,()->store.sample(ID,1,1,1));assertEquals(409,error.status);assertFalse(error.toString().contains("canary"));assertEquals(List.of(SqlServerProcedure.HEALTH_READY,SqlServerProcedure.HEALTH_SAMPLE),calls);assertEquals("rollback",manager.events.getLast());}

 void authority(String role,boolean tenant){request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",tenant?ID:null,List.of(role),"a".repeat(64)));if(tenant)request.setAttribute("health.tenant",new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","ACTIVE",List.of()));else request.removeAttribute("health.tenant");}
 void emptyRows(){results.add(new SqlServerExecutor.Result(List.of(List.of()),List.of()));}
 void detailsRows(boolean platform){row(Map.of("mode","MAINTENANCE","message","reason","revision",3));row(Map.of("ready",1));if(platform){row(Map.of("id",1L,"instanceId",ID,"dbStatus","DOWN","dbLatencyMs",0L,"memoryUsed",Long.MAX_VALUE,"memoryMax",0L,"uptimeMs",1L,"createdAt","2026-11-04T00:00:00.123456Z"));row(Map.of("status","PENDING","total",2L));}row(Map.of("statusGroup",500,"total",2L,"averageMs",Long.MAX_VALUE));if(platform){var migration=new LinkedHashMap<String,Object>();migration.put("version",null);migration.put("description","repeatable");migration.put("installedOn","2026-11-04T00:00:00Z");migration.put("success",true);migration.put("passwordHash","canary");row(migration);}}
 @Test void detailsPlatformExactSixSpContextsAndNullableImmutableProjection(){authority("SOP",false);detailsRows(true);var out=store.details(request);assertEquals(List.of(SqlServerProcedure.APPLICATION_STATUS,SqlServerProcedure.HEALTH_READY,SqlServerProcedure.MONITOR_SAMPLES,SqlServerProcedure.MONITOR_MAIL,SqlServerProcedure.MONITOR_REQUESTS,SqlServerProcedure.MONITOR_MIGRATIONS),calls);assertEquals(Set.of("application","database","samples","mail","requests","migrations"),out.keySet());for(int i=0;i<calls.size();i++){assertEquals(List.of(),args.get(i));assertEquals(SqlServerContext.Scope.REQUEST,contexts.get(i).scope());assertEquals(ID,contexts.get(i).actorId());assertNull(contexts.get(i).tenantId());}assertEquals(List.of("begin:0","commit"),manager.events);assertEquals("UP",((Map<?,?>)out.get("database")).get("status"));var samples=(List<Map<String,Object>>)out.get("samples");assertEquals("DOWN",samples.getFirst().get("dbStatus"));assertEquals(8,samples.getFirst().size());assertThrows(UnsupportedOperationException.class,samples::clear);var migrations=(List<Map<String,Object>>)out.get("migrations");assertNull(migrations.getFirst().get("version"));assertEquals(4,migrations.getFirst().size());assertThrows(UnsupportedOperationException.class,migrations.getFirst()::clear);assertThrows(UnsupportedOperationException.class,out::clear);}
 @Test void tenantDetailsOnlyThreeSpAndNoPlatformKeys(){authority("AUD",true);detailsRows(false);var out=store.details(request);assertEquals(List.of(SqlServerProcedure.APPLICATION_STATUS,SqlServerProcedure.HEALTH_READY,SqlServerProcedure.MONITOR_REQUESTS),calls);assertEquals(Set.of("application","database","samples","requests"),out.keySet());assertEquals(List.of(),out.get("samples"));for(var c:contexts)assertEquals(ID,c.tenantId());}
 @Test void modeWritesThenMapsStatusWithinOneRequiredContext(){authority("SAD",false);results.add(new SqlServerExecutor.Result(List.of(),List.of(0)));row(Map.of("mode","OPEN","message","  Preserved  ","revision",2));var out=store.mode(request,1,"OPEN","  Preserved  ");assertEquals("  Preserved  ",out.get("message"));assertEquals(List.of(SqlServerProcedure.APPLICATION_MODE,SqlServerProcedure.APPLICATION_STATUS),calls);assertEquals(List.of(1,"OPEN","  Preserved  "),args.getFirst());assertEquals(contexts.getFirst(),contexts.getLast());assertEquals(List.of("begin:0","commit"),manager.events);}
 @Test void detailsAndModeDirectAuthorityRejectBeforeExecutor(){for(String role:List.of("SAD","SOP","ADM","AUD","PRO"))for(boolean tenant:List.of(false,true)){authority(role,tenant);boolean allowed=tenant?List.of("ADM","AUD").contains(role):List.of("SAD","SOP").contains(role);if(!allowed)assertEquals(403,assertThrows(ApiException.class,()->store.details(request)).status);if(tenant||!role.equals("SAD"))assertEquals(403,assertThrows(ApiException.class,()->store.mode(request,1,"OPEN","reason")).status);}request.removeAttribute("health.actor");assertEquals(403,assertThrows(ApiException.class,()->store.details(request)).status);request.setAttribute("health.tenant","bad");safe(()->store.details(request));verifyNoInteractions(executor);}
 @Test void modeInvalidInputsNoWriteAndConflictNoStatusQuery(){authority("SAD",false);for(int revision:List.of(0,-1))assertEquals(400,assertThrows(ApiException.class,()->store.mode(request,revision,"OPEN","reason")).status);for(String mode:Arrays.asList(null,"open","INVALID"))assertEquals(400,assertThrows(ApiException.class,()->store.mode(request,1,mode,"reason")).status);for(String message:Arrays.asList(null," ","x".repeat(301)))assertEquals(400,assertThrows(ApiException.class,()->store.mode(request,1,"OPEN",message)).status);verifyNoInteractions(executor);doThrow(new RuntimeException(new java.sql.SQLException("canary conflict",null,51003))).when(executor).execute(any(),any(),any(Object[].class));assertEquals(409,assertThrows(ApiException.class,()->store.mode(request,1,"OPEN","reason")).status);verify(executor,times(1)).execute(any(),any(),any(Object[].class));assertEquals("rollback",manager.events.getLast());}
 @Test void malformedDetailMetricsTimestampsAndMigrationTypesRollback(){authority("SAD",false);for(Object bad:List.of(1,"1",-1L)){row(Map.of("mode","OPEN","message","","revision",1));row(Map.of("ready",1));row(Map.of("id",1L,"instanceId",ID,"dbStatus","UP","dbLatencyMs",bad,"memoryUsed",1L,"memoryMax",1L,"uptimeMs",1L,"createdAt","2026-11-04T00:00:00Z"));safe(()->store.details(request));assertEquals("rollback",manager.events.getLast());}row(Map.of("mode","OPEN","message","","revision",1));row(Map.of("ready",0));safe(()->store.details(request));assertEquals(SqlServerProcedure.HEALTH_READY,calls.getLast());}
 @Test void modeReadMappingFailureAndJoinedCancellationRollBackWithoutIndependentCommit(){authority("SAD",false);results.add(new SqlServerExecutor.Result(List.of(),List.of()));row(Map.of("mode","OPEN","message","","revision",0));safe(()->store.mode(request,1,"OPEN","reason"));results.add(new SqlServerExecutor.Result(List.of(),List.of()));row(Map.of("mode","OPEN","message","","revision",2));assertThrows(RuntimeException.class,()->manager.outer(()->{store.mode(request,1,"OPEN","reason");throw new RuntimeException("synthetic cancellation");}));assertEquals("rollback",manager.events.getLast());assertFalse(manager.events.contains("commit"));}

 void platformPrelude(){row(Map.of("mode","OPEN","message","","revision",1));row(Map.of("ready",1));emptyRows();emptyRows();}
 @Test void migrationAndAggregateMalformedRowsNeverProducePartialSnapshot(){authority("SAD",false);for(int mode=0;mode<3;mode++){platformPrelude();row(Map.of("statusGroup",200,"total",1L,"averageMs",0L));var m=new LinkedHashMap<String,Object>();m.put("version",mode==0?1:null);m.put("description","repeatable");m.put("installedOn",mode==1?"2026-11-04T00:00:00.123456789Z":"2026-11-04T00:00:00Z");m.put("success",mode==2?"true":true);row(m);safe(()->store.details(request));assertEquals("rollback",manager.events.getLast());}platformPrelude();row(Map.of("statusGroup",200L,"total",1L,"averageMs",0L));safe(()->store.details(request));assertEquals(SqlServerProcedure.MONITOR_REQUESTS,calls.getLast());}
 @Test void modeCommitFailureAndUnexpectedWriteRowsPropagate(){authority("SAD",false);emptyRows();safe(()->store.mode(request,1,"OPEN","reason"));assertEquals(List.of(SqlServerProcedure.APPLICATION_MODE),calls);results.add(new SqlServerExecutor.Result(List.of(),List.of()));row(Map.of("mode","MAINTENANCE","message","preserved","revision",2));manager.failCommit=true;safe(()->store.mode(request,1,"MAINTENANCE","preserved"));assertEquals(SqlServerProcedure.APPLICATION_STATUS,calls.getLast());}


 @Test void readyOneWorkerProbeZeroArgsAndNoSamplingOrHttpAuthority(){var prior=new MockHttpServletRequest("POST","/private-canary");var actor=new Actor(ID,"Synthetic","synthetic@example.test",ID,List.of("SAD"),"a".repeat(64));var tenant=new TenantRef(ID,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of());prior.setAttribute("health.actor",actor);prior.setAttribute("health.tenant",tenant);TraceContext.REQUEST.set(prior);var authentication=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(actor,"private-canary",List.of());SecurityContextHolder.getContext().setAuthentication(authentication);row(Map.of("ready",1));store.ready();assertEquals(List.of(SqlServerProcedure.HEALTH_READY),calls);assertEquals(List.of(List.of()),args);assertEquals(List.of(new SqlServerContext(null,null,null,null,null,null,null,null,null,SqlServerContext.Scope.WORKER)),contexts);assertEquals(List.of("begin:0","commit"),manager.events);assertSame(prior,TraceContext.REQUEST.get());assertSame(actor,prior.getAttribute("health.actor"));assertSame(tenant,prior.getAttribute("health.tenant"));assertSame(authentication,SecurityContextHolder.getContext().getAuthentication());verify(executor,times(1)).execute(eq(SqlServerProcedure.HEALTH_READY),any(),any(Object[].class));}
 @Test void readyRejectsEveryMalformedResultBeforeCommitWithoutRetry(){var bad=new ArrayList<SqlServerExecutor.Result>();bad.add(new SqlServerExecutor.Result(List.of(),List.of()));bad.add(new SqlServerExecutor.Result(List.of(List.of()),List.of()));bad.add(new SqlServerExecutor.Result(List.of(List.of(Map.of("ready",1),Map.of("ready",1))),List.of()));bad.add(new SqlServerExecutor.Result(List.of(List.of(Map.of("ready",1)),List.of()),List.of()));bad.add(new SqlServerExecutor.Result(List.of(List.of(Map.of())),List.of()));for(Object value:Arrays.asList(null,0,2,-1,1L,"1",true)){var r=new LinkedHashMap<String,Object>();r.put("ready",value);bad.add(new SqlServerExecutor.Result(List.of(List.of(r)),List.of()));}for(var result:bad){int before=calls.size();results.add(result);safe(store::ready);assertEquals(before+1,calls.size());assertEquals("rollback",manager.events.getLast());}assertFalse(manager.events.contains("commit"));assertTrue(calls.stream().allMatch(sp->sp==SqlServerProcedure.HEALTH_READY));doReturn(null).when(executor).execute(any(),any(),any(Object[].class));safe(store::ready);}
 @Test void readyRequiredJoinsAndOuterCancellationOrMappingErrorRollsBack(){row(Map.of("ready",1));manager.outer(()->{store.ready();assertEquals(List.of("begin:0"),manager.events);return null;});assertEquals(List.of("begin:0","commit"),manager.events);manager.events.clear();row(Map.of("ready",1));assertThrows(RuntimeException.class,()->manager.outer(()->{store.ready();throw new RuntimeException("synthetic cancellation");}));assertEquals(List.of("begin:0","rollback"),manager.events);manager.events.clear();row(Map.of("ready",0));safe(()->manager.outer(()->{store.ready();return null;}));assertTrue(manager.events.contains("rollbackOnly"));assertEquals("rollback",manager.events.getLast());}
 @Test void readyCommitFailureHasNoSuccessfulReturn(){row(Map.of("ready",1));manager.failCommit=true;safe(store::ready);assertEquals(List.of(SqlServerProcedure.HEALTH_READY),calls);verify(executor,times(1)).execute(any(),any(),any(Object[].class));}
 @Test void readyVendorExceptionsStaySafeAndNeverRetryOrRunAnotherDescriptor(){for(int code:List.of(51000,51001,51002,51003,51004,51005,229,99999)){clearInvocations(executor);doThrow(new RuntimeException(new java.sql.SQLException("private-canary",null,code))).when(executor).execute(any(),any(),any(Object[].class));var e=assertThrows(ApiException.class,store::ready);assertEquals(switch(code){case 51000->400;case 51001,51004->403;case 51002->404;case 51003,51005->409;default->500;},e.status);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));assertEquals("rollback",manager.events.getLast());verify(executor,times(1)).execute(eq(SqlServerProcedure.HEALTH_READY),any(),any(Object[].class));}}
}
